package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchUsers handles user search with filtering
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	department := r.URL.Query().Get("dept")
	sortCol := r.URL.Query().Get("sort")
	nameFilter := r.URL.Query().Get("name")

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"username": true, "email": true, "created_at": true, "department": true}
	if sortCol == "" || !allowedSorts[sortCol] {
		sortCol = "username"
	}

	// Build query - department is parameterized, but nameFilter uses LIKE
	// Note: nameFilter is sanitized by escaping single quotes
	nameFilter = strings.ReplaceAll(nameFilter, "'", "''")

	query := fmt.Sprintf(
		"SELECT username, email, department FROM users WHERE department = $1 AND username LIKE '%%%s%%' ORDER BY %s LIMIT 50",
		nameFilter,
		sortCol,
	)

	rows, err := db.Query(query, department)
	if err != nil {
		http.Error(w, "Query error: "+err.Error(), 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var username, email, dept string
		rows.Scan(&username, &email, &dept)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`  {"username":"%s","email":"%s","department":"%s"}`, username, email, dept)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// deleteUser removes a user account
func deleteUser(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	userID := r.FormValue("user_id")
	if userID == "" {
		http.Error(w, "Missing user_id", 400)
		return
	}
	// Direct string interpolation - SQL injection
	query := fmt.Sprintf("DELETE FROM users WHERE id = '%s'", userID)
	_, err := db.Exec(query)
	if err != nil {
		http.Error(w, "Delete failed: "+err.Error(), 500)
		return
	}
	w.Write([]byte(`{"status":"deleted"}`))
}

// updateBio updates user biography
func updateBio(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}
	userID := r.FormValue("user_id")
	bio := r.FormValue("bio")
	// Parameterized - safe
	_, err := db.Exec("UPDATE users SET bio = $1 WHERE id = $2", bio, userID)
	if err != nil {
		http.Error(w, "Update failed", 500)
		return
	}
	w.Write([]byte(`{"status":"updated"}`))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/api/users/delete", deleteUser)
	http.HandleFunc("/api/users/bio", updateBio)
	http.ListenAndServe(":8080", nil)
}
